insert into public.programs (id, kind, name, college, catalog, min_total_credits, min_gpa, notes, source_url, sort_order, excluded_programs) values
('fisher-bsba', 'degree', 'Bachelor of Science in Business Administration (BSBA)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', 121, 2.0, 'Minimum 121 credit hours and a 2.0 cumulative GPA in the specialization. General Education totals 32-39 credit hours; business foundation courses also count toward GE Writing, Math & Quantitative Reasoning, and Social & Behavioral Sciences. Requirements change for students who begin in Autumn 2027 or later.', 'https://fisher.osu.edu/undergraduate/academics/curriculum-requirements', 0, '{}'::text[]),
('spec-accounting', 'specialization', 'Accounting', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/accounting', 1, '{}'::text[]),
('spec-aviation-management', 'specialization', 'Aviation Management', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'Offered with the Center for Aviation Studies. Students in this track can''t enroll in the Professional Pilot Certification.', 'https://fisher.osu.edu/undergraduate/academics/specializations/aviation-management', 2, '{}'::text[]),
('spec-business-management', 'specialization', 'Business Management (regional campuses)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'Offered on regional campuses. Columbus students follow the prerequisites on each course''s own specialization sheet.', 'https://fisher.osu.edu/undergraduate/academics/specializations/business-management', 3, '{}'::text[]),
('spec-economics', 'specialization', 'Economics', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'Economics students must earn a C- or higher in ECON 2001 and ECON 2002.', 'https://fisher.osu.edu/undergraduate/academics/specializations/economics', 4, '{}'::text[]),
('spec-finance', 'specialization', 'Finance', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/finance', 5, '{}'::text[]),
('spec-human-resources', 'specialization', 'Human Resources', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/human-resources', 6, '{}'::text[]),
('spec-information-systems', 'specialization', 'Information Systems', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/information-systems', 7, '{}'::text[]),
('spec-international-business', 'specialization', 'International Business', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/international-business', 8, '{}'::text[]),
('spec-logistics-management', 'specialization', 'Logistics Management', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/logistics-management', 9, '{}'::text[]),
('spec-marketing', 'specialization', 'Marketing', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/marketing', 10, '{}'::text[]),
('spec-operations-management', 'specialization', 'Operations Management (Operations track)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/operations-management', 11, '{}'::text[]),
('spec-operations-purchasing', 'specialization', 'Operations Management (Purchasing track)', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/operations-management', 12, '{}'::text[]),
('spec-tech-innovation', 'specialization', 'Tech Innovation', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, 'New in Autumn 2026 (approved by the Council on Academic Affairs, Feb 2026). Requires an application in year 1 (minimum 3.0 GPA) and starts in year 2 with a one-semester immersion, then one Builders Studio course each semester junior and senior year with corporate-sponsored projects. Takes at least 5 semesters.', 'https://oaa.osu.edu/sites/default/files/documents/FCOB%20-%20Proposal%20to%20establish%20a%20Tech%20Innovation%20Specialization%20in%20the%20Business%20Administration%20major.pdf', 13, '{}'::text[]),
('spec-real-estate', 'specialization', 'Real Estate', 'Fisher College of Business', 'Fisher BSBA, enrollment Spring 2027 and prior', null, null, null, 'https://fisher.osu.edu/undergraduate/academics/specializations/real-estate', 14, '{}'::text[])
